f ( - x ) = - \frac { 2 } { 3 ^ { - x } + 1 }
= - \frac { 1 } { \frac { 1 } { 3 ^ { x } } + 1 }
= - \frac { 2 3 ^ { x } } { 3 ^ { x } + 1 }
\because \vert f ( - x ) - ( - 1 ) \vert = - \frac { 2 3 ^ { x } } { 3 ^ { x } + 1 } + 1 = \frac { 3 ^ { x } - 1 \delete } { 3 ^ { x } + 1 }
f ( x ) - \delete ( - 1 ) = - \frac { 2 } { 3 ^ { x } + 1 } + 1 = \frac { 3 ^ { x } - 1 } { 3 ^ { x } + 1 }
\because \vert f ( - x ) - \delete ( - 1 ) \vert = \vert f ( x ) - ( - 1 ) \vert
\because x 与 - x 关 于 0 对 称
\therefore f ( x ) 的 图 象 关 于 ( 0 , - 1 ) 对 称
( 2 ) \because f ( m \cdot 9 ^ { x } + 1 ) + f ( - 3 ) \leq - 2
\because f ( - 3 ) + f ( 3 ) = - 2
\therefore m \cdot 9 ^ { x } + 1 \leq 3
m \cdot 9 ^ { x } \leq 2
\because 存 在 正 数 x 使 m \cdot 9 ^ { x } \leq 2 成 立
\therefore 9 ^ { x } > 1
\therefore m < 2

